T["Die Gildenleitung benennt Schlachtzugsleiter und Assistenz unter Krone > Module > Raids & Beute (Namen oder ab Gildenrang). Im laufenden Raid zaehlen auch Raidleiter und Assistenten."] = "公會管理在王冠 > 模組 > 團隊與戰利品中指定團隊領袖和助理（名字或按公會會階）。進行中的團隊副本中，團隊領袖和助理也算。"
T["Die Gildenleitung benennt Schlachtzugsleiter unter Krone > Module > Raids & Beute. Im laufenden Raid zaehlen auch Raidleiter und Assistenten."] = "公會管理在王冠 > 模組 > 團隊與戰利品中指定團隊領袖。進行中的團隊副本中，團隊領袖和助理也算。"
T["Die Gildenleitung benennt Schlachtzugsleiter unter Krone > Module > Raids & Beute. Im laufenden Raid zaehlt auch der Raidleiter."] = "公會管理在王冠 > 模組 > 團隊與戰利品中指定團隊領袖。進行中的團隊副本中，團隊領袖也算。"
T["Die Gildenleitung erlaubt Gruppensuchen erst ab einem hoeheren Rang."] = "公會管理只允許更高會階建立組隊招募。"
T["Die Gildenleitung erlaubt Umfragen erst ab einem hoeheren Rang."] = "公會管理只允許更高會階建立投票。"
T["Die Gildenleitung hat die Mitstreiter-Suche abgeschaltet."] = "公會管理已關閉尋找夥伴功能。"
T["Die Gildenleitung hat offene Einladungen abgeschaltet - fordere jemanden direkt heraus."] = "公會管理已關閉公開邀請 - 請直接挑戰某人。"
T["Die Gildenleitung legt unter Krone > Module fest, welche Raenge das duerfen."] = "公會管理在王冠 > 模組中設定哪些會階有此許可權。"
T["Die Gildensuche von WoW hilft beim Finden - neutral, ohne Werbung."] = "魔獸的公會查詢器可幫助尋找 - 中立，無廣告。"
T["Die Grenze legt nur der Gildenmeister fest. Rang 1 = Gildenmeister."] = "上限只能由會長設定。會階1 = 會長。"
T["Die Knoepfe schreiben den Befehl in die Chatzeile - erst mit Enter wird er ausgefuehrt."] = "按鈕會將命令寫入聊天欄 - 按回車後才執行。"
T["Die Kuerzel stehen auch in WoWs Tastaturbelegung unter AddOns > Oasis. Esc schliesst das Oasis-Fenster (im Kampf nicht - dort gehoert Esc dem Spiel)."] = "這些快捷鍵也在魔獸按鍵設定的外掛 > Oasis中。Esc關閉Oasis視窗（戰鬥中不行 - 那時Esc歸遊戲使用）。"
T["Die Kuerzel stehen auch in WoWs Tastaturbelegung unter AddOns > Oasis. Esc schliesst das Oasis-Fenster, solange du zuletzt hineingeklickt hast."] = "這些快捷鍵也在魔獸按鍵設定的外掛 > Oasis中。只要你最後點選過Oasis視窗，Esc就會關閉它。"
T["Die Leiste rollt nach oben weg; Maus an den oberen Rand und sie kommt herunter (nur wenn sie oben angedockt ist)"] = "工具欄會向上收起；將滑鼠移到螢幕頂部邊緣它會下來（僅在頂部停靠時）"
T["Die Reservierungs-Zeile erscheint nur, wenn du in einer Gruppe oder einem Schlachtzug bist"] = "預定行僅在你處於隊伍或團隊中時顯示"
T["Die Waechter der Sande"] = "流沙守望者"
T["Die Weltkarte geoeffnet. Wo war nochmal Norden?"] = "打開了世界地圖。北邊在哪來著？"
T["Die echte Leiste oben zeigt jede Aenderung sofort"] = "頂部的真實工具欄會立即顯示每項更改"
T["Die ersten 20 Ausdauer geben je 1, jeder weitere Punkt 10 Gesundheit."] = "前20點耐力每點提供1生命值，之後每點提供10生命值。"
T["Die meisten Geisterlaeufe der Gilde. Der Friedhof hat eine Bank mit deinem Namen."] = "公會中跑屍次數最多。墓地有一張刻著你名字的長椅。"
T["Die meisten Screenshots der Gilde"] = "公會中截圖最多"
T["Die meisten Tode der letzten 7 Tage"] = "最近7天死亡最多"
T["Die meisten vollen Taschen der Gilde"] = "公會中背包滿最多次"
T["Die neueste Durchsage steht 3 Tage oben auf der Uebersicht."] = "最新公告在概覽頂部顯示3天。"
T["Die vergessenen Teiche"] = "遺忘之池"
T["Diese Abzeichen zeigt deine Profilkarte zuerst - bei dir und bei der Gilde."] = "這些徽章會優先顯示在你的資料卡上 - 對你和公會都是。"
T["Diese Hinweise ausschalten"] = "關閉這些提示"
T["Diese Quest hat %s, nicht du."] = "這個任務是%s的，不是你的。"
T["Diese Quest ist nicht in deinem Questlog."] = "這個任務不在你的任務日誌中。"
T["Diese Regel gibt es schon."] = "該規則已存在。"
T["Diese Seiten stehen als kleine Knoepfe in der eingeklappten Oasis-Leiste - ein Klick oeffnet sie direkt."] = "這些頁面以小按鈕形式顯示在摺疊的Oasis工具欄中 - 點選即可直接開啟。"
T["Diese Sitzung: %d EP in %s"] = "本次會話：%d經驗（用時%s）"
T["Diese Sprache gilt nach dem naechsten /reload - hier klicken zum Neuladen."] = "該語言將在下次/reload後生效 - 點選此處過載。"
T["Diese Taktik ist noch leer."] = "該戰術尚為空。"
T["Diese Woche ist noch alles offen - wer macht den Anfang?"] = "本週還都沒完成 - 誰來開個頭？"
T["Diese Woche:"] = "本週："
T["Dieser Client hat keine Sammlungs-Schnittstelle. /oa probe sammlung zeigt Details."] = "此客戶端沒有收藏介面。/oa probe sammlung顯示詳情。"
T["Dieser Client liefert keine Rufdaten - du siehst nur die Staende der anderen."] = "此客戶端不提供聲望資料 - 你只能看到其他人的進度。"
T["Dieser Client meldet keine seltenen Gegner (Schnittstelle fehlt). /oa probe rares zeigt Details."] = "此客戶端不報告稀有敵人（缺少介面）。/oa probe rares顯示詳情。"
T["Dir fehlt nichts, was die Gilde hat - stark!"] = "公會有的你都不缺 - 厲害！"
T["Dir selbst etwas zugefluestert. Wer sonst hoert dir so gut zu?"] = "給自己發了密語。還有誰會這麼認真聽你說話？"
T["Discord-Bruecke: Ist sie an, speichert WoW den ganzen Chat (auch Fluestern) im Klartext in Logs/WoWChatLog.txt."] = "Discord橋接：開啟後，魔獸會將全部聊天（包括密語）以明文儲存在Logs/WoWChatLog.txt中。"
T["Discord-Link"] = "Discord連結"
T["Discord-Link - z.B. discord.gg/deinegilde (Enter speichert)"] = "Discord連結 - 例如discord.gg/你的公會（回車儲存）"
T["Discord-Nachrichten im Gildenchat zeigen (ueber OasisSync, nach /reload)"] = "在公會聊天中顯示Discord訊息（通過OasisSync，/reload後）"
T["Discord-Nachrichten uebernommen: %d (neue erscheinen erst nach /reload)"] = "已匯入Discord訊息：%d條（新訊息在/reload後顯示）"
