T["Noch kein Termin - melde dein Interesse, dann weiss die Raidleitung, wann es passt."] = "還沒有活動 - 表示興趣，團隊領導就知道何時合適。"
T["Noch kein Tod - weiter so!"] = "還沒有死亡 - 繼續保持！"
T["Noch kein Tod eines seltenen Gegners erfasst."] = "尚未記錄稀有敵人的死亡。"
T["Noch keine Abklingzeiten geteilt - wer Transmutation, Mondstoff oder einen Salzstreuer hat, erscheint hier."] = "還沒有共享冷卻 - 擁有轉化、月布或鹽瓶的人會顯示在這裡。"
T["Noch keine Abzeichen"] = "還沒有徽章"
T["Noch keine Ausruestung bekannt - Spieler in der Naehe anvisieren und betrachten (Oasis betrachtet Mitspieler in der Gruppe automatisch)."] = "還不知道裝備 - 選中附近的玩家並觀察（Oasis會自動觀察隊伍中的隊友）。"
T["Noch keine Berufe gelernt."] = "還沒有學習專業。"
T["Noch keine Beute aus diesem Dungeon im Gilden-Log."] = "公會日誌中還沒有此地下城的戰利品。"
T["Noch keine Beute erfasst"] = "尚未記錄戰利品"
T["Noch keine Bewerber. Name oben eintragen - Klick auf den Status schaltet weiter."] = "還沒有申請者。在上方輸入名字 - 點選狀態切換。"
T["Noch keine Daten - Ausruestung kommt mit dem naechsten Abgleich der Oasis-Nutzer."] = "還沒有資料 - 裝備會隨Oasis使用者的下次同步而來。"
T["Noch keine Daten - Mitglieder schicken ihre Messung alle 15 Min (ab dieser Version)."] = "還沒有資料 - 成員每15分鐘傳送測量結果（從此版本起）。"
T["Noch keine Daten - oeffne einmal das Sammlungsfenster oder trage Reittiere und Haustiere in der Tasche. Sobald Gildenmitglieder mit Oasis online sind, erscheinen sie hier."] = "還沒有資料 - 開啟一次收藏視窗或在背包中攜帶坐騎和寵物。一旦有Oasis的公會成員線上，就會顯示在這裡。"
T["Noch keine Daten von der Gilde."] = "還沒有來自公會的資料。"
T["Noch keine Daten. Sobald Gildenmitglieder mit Oasis einloggen, erscheinen ihre Raid-IDs hier."] = "還沒有資料。一旦有Oasis的公會成員登入，他們的團隊副本ID就會顯示在這裡。"
T["Noch keine Dungeon-Laeufe aufgezeichnet."] = "還沒有記錄地下城次數。"
T["Noch keine Dungeons geplant."] = "還沒有計劃地下城。"
T["Noch keine Eintraege."] = "還沒有條目。"
T["Noch keine Emojis benutzt - Favoriten aus der Emoji-Auswahl erscheinen hier."] = "還沒有使用過表情 - 表情選擇中的收藏會顯示在這裡。"
T["Noch keine Favoriten - Diamant anklicken."] = "還沒有收藏 - 點選菱形。"
T["Noch keine Favoriten - Stern oder Rechtsklick auf einen Sound."] = "還沒有收藏 - 點選星標或右鍵點選音效。"
T["Noch keine Favoriten.\nRechtsklick auf ein Emoji merkt es hier."] = "還沒有收藏。\n右鍵點選表情即可收藏到這裡。"
T["Noch keine Fluesternachrichten."] = "還沒有密語。"
T["Noch keine Fluesternachrichten. Schreib jemandem aus der Gilde!"] = "還沒有密語。給公會裡的人寫一條吧！"
T["Noch keine Fraktionen entdeckt."] = "還沒有發現陣營。"
T["Noch keine Gildenziele. Lege das erste an - z. B. eine legendaere Waffe oder Material fuer den Raid."] = "還沒有公會目標。建立第一個 - 例如一把傳說武器或團隊副本材料。"
T["Noch keine Kampfberichte. Nach dem ersten Bosskampf steht hier jeder Versuch - mit Zeitstrahl der Tode und wiederkehrenden Mustern."] = "還沒有戰鬥報告。第一場首領戰後這裡會顯示每次嘗試 - 帶死亡時間線和重複模式。"
T["Noch keine Kampfberichte. Nach dem ersten Bosskampf steht hier jeder Versuch."] = "還沒有戰鬥報告。第一場首領戰後這裡會顯示每次嘗試。"
T["Noch keine Kandidaten. Spiel mit Leuten ausserhalb der Gilde - wer ohne Gilde ist und gut bewertet wird, landet hier."] = "還沒有候選人。和公會外的人一起玩 - 無公會且評價良好的人會出現在這裡。"
T["Noch keine Kombos.\nShift+Klick auf mehrere Emojis, dann Merken."] = "還沒有組合。\nShift+點選多個表情，然後收藏。"
T["Noch keine Kontakte. Geh mit anderen Oasis-Nutzern in eine Gruppe - Oasis merkt sie sich dann hier, auch ohne Gilde."] = "還沒有聯絡人。與其他Oasis使用者組隊 - Oasis會在這裡記住他們，即使不在公會。"
T["Noch keine Meilensteine. Level auf, lern Berufe - hier entsteht deine Geschichte."] = "還沒有里程碑。升級、學專業 - 你的故事從這裡開始。"
T["Noch keine Meldungen aus der Gilde."] = "還沒有來自公會的報告。"
T["Noch keine Momente - spiel einfach, Oasis schreibt mit."] = "還沒有精彩瞬間 - 儘管玩吧，Oasis會記錄。"
T["Noch keine Nachrichten im Offizierschat. Alles, was ab jetzt im Kanal /o geschrieben wird, steht hier."] = "官員聊天中還沒有訊息。從現在起在/o頻道寫的所有內容都會顯示在這裡。"
T["Noch keine Positionen - die Karte fuellt sich, sobald Mitglieder mit Oasis unterwegs sind."] = "還沒有位置 - 一旦有Oasis的成員在外活動，地圖就會填滿。"
T["Noch keine Preise. Sobald jemand mit Midas im AH scannt, stehen sie hier."] = "還沒有價格。一旦有人用Midas掃描拍賣行，就會顯示在這裡。"
T["Noch keine Profile gespeichert."] = "還沒有儲存的配置。"
T["Noch keine Punkte"] = "還沒有點數"
T["Noch keine Raidtage erfasst. Der Raidleiter (mit Oasis) schreibt sie bei jedem Boss-Kill automatisch mit."] = "還沒有記錄團隊日。團隊領袖（裝有Oasis）會在每次擊殺首領時自動記錄。"
T["Noch keine Regeln"] = "還沒有規則"
T["Noch keine Regeln. Nimm eine Schnell-Vorlage oder leg oben eine eigene an."] = "還沒有規則。選擇一個快速模板或在上方建立自己的規則。"
T["Noch keine Rufdaten. Sie kommen automatisch, sobald Mitglieder mit Oasis online sind."] = "還沒有聲望資料。一旦有Oasis的成員線上就會自動獲取。"
T["Noch keine Sammlung geteilt. Sobald Gildenmitglieder mit Oasis online sind, erscheinen sie hier."] = "還沒有共享收藏。一旦有Oasis的公會成員線上，就會顯示在這裡。"
T["Noch keine Sets."] = "還沒有套裝。"
T["Noch keine Sichtung. Sobald jemand mit Oasis einen seltenen Gegner sieht, steht er hier."] = "還沒有發現。一旦有Oasis使用者看到稀有敵人，就會顯示在這裡。"
T["Noch keine Spielzeiten bekannt. Oasis lernt mit jedem Abend, an dem du online bist - und uebernimmt die Profile der anderen."] = "還不知道遊戲時間。Oasis會在你每晚線上時學習 - 並採用其他人的資料。"
T["Noch keine Suche. Level eingeben und \"Suchen\" klicken - Spieler mit Gilde werden ausgeblendet."] = "還沒有搜尋。輸入等級並點選\"搜尋\" - 有公會的玩家會被隱藏。"
T["Noch keine Taktiken."] = "還沒有戰術。"
T["Noch keine Taktiken. Die Raidleitung kann je Boss eine kurze Taktik anlegen - alle sehen sie hier und bekommen sie beim Anvisieren angezeigt."] = "還沒有戰術。團隊領導可以為每個首領建立簡短戰術 - 所有人都能在這裡看到，選中首領時也會顯示。"
T["Noch keine Talente bekannt. Mitglieder mit Oasis teilen sie automatisch; andere Spieler: anvisieren und betrachten (Rechtsklick > Betrachten) oder hier mit Ziel erneut oeffnen."] = "還不知道天賦。Oasis成員會自動共享；其他玩家：選中並觀察（右鍵 > 觀察）或選中目標後重新開啟此處。"
T["Noch keine Vergaben - sie erscheinen hier, sobald die Raidleitung Beute verteilt."] = "還沒有分配 - 團隊領導分配戰利品後會顯示在這裡。"
T["Noch keine Werte - nach dem naechsten Kampf erscheint hier, wer vorne liegt."] = "還沒有數值 - 下一場戰鬥後這裡會顯示誰領先。"
T["Noch keine Wunschtage - tippe an, wann du kannst."] = "還沒有期望日期 - 點選你有空的時間。"
T["Noch keine Wunschtage gemeldet."] = "還沒有人報告期望日期。"
T["Noch keine Ziele. Leg oben eins an - Oasis hakt es automatisch ab."] = "還沒有目標。在上方建立一個 - Oasis會自動勾選。"
T["Noch keine Zusagen - sei der Erste!"] = "還沒有人確認 - 來當第一個吧！"
T["Noch keine eigene Beute"] = "還沒有自己的戰利品"
T["Noch keine eigene Beute erfasst (ab Qualitaet 'Selten', einstellbar)."] = "還沒有記錄自己的戰利品（從“精良”品質起，可調整）。"
T["Noch nicht angemeldet - waehle unten deine Rolle"] = "尚未報名 - 在下方選擇你的職責"
T["Noch nicht bereit"] = "尚未就緒"
T["Noch nicht fuer die Gilde uebernommen:"] = "尚未為公會接管："
T["Noch nicht kalibriert - Kalibrieren?"] = "尚未校準 - 校準？"
T["Noch nichts auf der Wunschliste.\nTrag oben ein, was du brauchst - alle mit Oasis sehen es im Tooltip und beim Looten."] = "願望單還是空的。\n在上方填寫你需要的東西 - 所有Oasis使用者都會在滑鼠提示和拾取時看到。"
T["Noch nichts aufgezeichnet."] = "還沒有記錄。"
T["Noch nichts benutzt."] = "還沒有使用。"
T["Noch nichts blockiert. Sobald WoW Oasis blockiert, steht hier welche Funktion und was Oasis kurz vorher gemacht hat."] = "還沒有攔截。一旦魔獸攔截Oasis，這裡會顯示哪個功能以及Oasis之前做了什麼。"
T["Noch nichts eingelesen"] = "尚未讀取"
T["Noch nichts geangelt."] = "還沒有釣到東西。"
T["Noch nichts gemerkt - Rechtsklick auf eine Nachricht: Nachricht merken."] = "還沒有收藏 - 右鍵點選訊息：收藏訊息。"
T["Noch nichts passiert - zieht los und schreibt Geschichte!"] = "還沒發生什麼 - 出發去書寫歷史吧！"
T["Noch nichts reserviert"] = "尚未預定"
T["Noch nichts reserviert - ein Item pro Termin."] = "尚未預定 - 每個活動一件物品。"
T["Noch nichts reserviert."] = "尚未預定。"
T["Noch nichts verkauft."] = "還沒有賣出東西。"
T["Noch nichts verteilt. Sobald eine Regel greift, steht es hier."] = "還沒有分配。一旦有規則生效，就會顯示在這裡。"
T["Noch nie direkt mit dir abgeglichen"] = "從未與你直接同步"
T["Noch niemand angefluestert."] = "還沒有密語過任何人。"
T["Noch niemand aus der Gilde hat es uebrig."] = "公會中還沒有人有多餘的。"
T["Noch niemand aus der Gilde mit deiner Spezialisierung teilt seine Talente (Oasis-Nutzer teilen automatisch)."] = "公會中還沒有與你同專精的人共享天賦（Oasis使用者會自動共享）。"
T["Noch niemand gegangen, seit Oasis mitschreibt."] = "自Oasis開始記錄以來還沒有人離開。"
T["Noch niemand gemeldet - sei der Erste!"] = "還沒有人報名 - 來當第一個吧！"
T["Noch niemand sonst kennt das Rezept."] = "還沒有其他人會這個配方。"
T["Noch niemand teilt seine Handelsbilanz."] = "還沒有人共享交易收支。"
T["Noch niemand teilt seine Handelsbilanz. Unten 'Bilanz teilen' einschalten - dann geht's los."] = "還沒有人共享交易收支。在下方開啟“共享收支” - 就開始了。"
T["Noch teilt niemand mit Oasis handelbare Teile. Je mehr Mitglieder Oasis nutzen, desto voller wird es hier."] = "還沒有人通過Oasis共享可交易物品。使用Oasis的成員越多，這裡就越豐富。"
T["Noch zu uebergeben"] = "仍需交付"
T["Noch zu wenig Daten fuer eine Stosszeit"] = "資料不足，無法得出高峰時間"
T["Normal"] = "普通"
T["Normal meldet Oasis nur Suchen, die du selbst noch offen hast"] = "通常Oasis只提醒你自己仍在進行的招募"
T["Notiz (Klasse, Kontakt, Eindruck ...)"] = "備註（職業、聯絡方式、印象……）"
T["Notiz an den Plundermeister (optional)"] = "給拾取者的備註（可選）"
T["Notiz der Gildenleitung"] = "公會管理備註"
T["Notiz von %s: %s"] = "%s的備註：%s"
T["Notiz zu %s"] = "關於%s的備註"
T["Notiz zur Person"] = "關於此人的備註"
T["Notiz zur Suche (Zeit, Treffpunkt) ..."] = "招募備註（時間、集合點）……"
T["Notizen sehen und schreiben nur Offiziere."] = "只有官員能檢視和編寫備註。"
T["Nur %s"] = "僅%s"
T["Nur Abende vorschlagen"] = "僅建議晚上"
T["Nur Banner und drei Spalten (wer ist online, was passiert, als Naechstes) - ohne Kacheln und Highlight-Zeile"] = "僅橫幅和三欄（誰線上、發生了什麼、接下來）- 無圖塊和亮點行"
T["Nur Dungeons, deren Beute besser ist als deine angelegte Ausruestung."] = "僅顯示戰利品比你已裝備的更好的地下城。"
T["Nur Eintraege dieser Person"] = "僅此人的條目"
T["Nur Farbverlauf"] = "僅漸變"
T["Nur Gegner im Kampf"] = "僅戰鬥中的敵人"
T["Nur Gildenleitung"] = "僅公會管理"
T["Nur Gruppenquests beruecksichtigen"] = "僅考慮組隊任務"
T["Nur Lagerfeuer in meinem Gebiet melden"] = "僅報告我所在區域的篝火"
T["Nur Mains ab Level"] = "僅大號，最低等級"
T["Nur Mitglieder bis zu diesem Rang duerfen eine Gruppensuche starten (10 = alle)."] = "僅此會階及以上的成員可以發起組隊招募（10 = 所有人）。"
T["Nur Mitglieder bis zu diesem Rang duerfen eine neue Umfrage starten (10 = alle)."] = "僅此會階及以上的成員可以發起新投票（10 = 所有人）。"
T["Nur Mitglieder mit Oasis. Geteilt werden offene Questitems, uebrige Questitems und teilbare Quests."] = "僅限有Oasis的成員。共享未完成的任務物品、多餘的任務物品和可共享的任務。"
T["Nur Oasis-Spieler"] = "僅Oasis玩家"
T["Nur Oasis-Spieler: jeder sieht sie in seiner eigenen Sprache."] = "僅Oasis玩家：每人以自己的語言檢視。"
T["Nur Offiziere und Gildenleitung sehen diesen Kanal (/o)."] = "只有官員和公會管理能看到此頻道（/o）。"
T["Nur Plundermeister, Anfuehrer oder Assistenten koennen verteilen."] = "只有拾取者、隊長或助理可以分配。"
T["Nur Rezepte, die du selbst kannst"] = "僅顯示你會的配方"
T["Nur Rezepte, die gerade jemand online herstellen kann"] = "僅顯示當前線上有人能製作的配方"
T["Nur Upgrades"] = "僅提升裝備"
T["Nur an die eigene Gruppe, fuer die Dungeon-Karte"] = "僅發給自己的隊伍，用於地下城地圖"
T["Nur ansehen - bearbeiten: Leitung, Schlachtzugsleiter, Raid-Assistenten"] = "僅檢視 - 可編輯：管理、團隊領袖、團隊助理"
T["Nur ansehen - zeichnen darf der Raidleiter"] = "僅檢視 - 只有團隊領袖可以繪製"
T["Nur auf diesem PC"] = "僅限此電腦"
T["Nur ausgeblendet - klick hier, um zurueckzukehren."] = "僅隱藏 - 點選此處返回。"
T["Nur bei dir"] = "僅限你"
T["Nur bei dir gespeichert"] = "僅儲存在你本地"
T["Nur bei gleicher Klasse und Spezialisierung."] = "僅限相同職業和專精。"
T["Nur das Noetigste"] = "僅保留必需"
T["Nur der Gildenmeister kann das aendern."] = "只有會長能更改此項。"
T["Nur der Gildenmeister, hoechstens 10 Raenge."] = "僅限會長，最多10個會階。"
T["Nur der Gruppenleiter kann eine Suche starten."] = "只有隊長能發起招募。"
T["Nur der Gruppenleiter kann suchen"] = "只有隊長能招募"
T["Nur die Gildenleitung kann das aendern."] = "只有公會管理能更改此項。"
T["Nur die Gildenleitung kann die Deathroll-Rangliste zuruecksetzen."] = "只有公會管理能重置死亡骰子排行榜。"
T["Nur die wichtigsten Bereiche sind an."] = "僅開啟了最重要的模組。"
T["Nur diese Person hoert ihn (wenn sie Oasis hat)."] = "只有此人能聽到（如果他有Oasis）。"
T["Nur diesen Abschnitt posten"] = "僅釋出此部分"
T["Nur fehlende"] = "僅缺少的"
T["Nur fuer Anfuehrer und Assistenten"] = "僅限隊長和助理"
T["Nur fuer Offiziere"] = "僅限官員"
T["Nur fuer Schlachtzugsleiter"] = "僅限團隊領袖"
T["Nur fuer Schlachtzugsleiter & Assistenz"] = "僅限團隊領袖和助理"
T["Nur fuer Umfragen, die du gestartet oder bei denen du abgestimmt hast"] = "僅限你發起或參與投票的投票"
T["Nur fuer den Schlachtzugsleiter"] = "僅限團隊領袖"
T["Nur fuer dich sichtbar - steht im Kopf des Gespraechs mit %s."] = "僅你可見 - 顯示在與%s的對話頂部。"
T["Nur fuer dich: nach dem Kampf eine Zeile mit Dauer und erstem Tod"] = "僅你可見：戰鬥後顯示一行時長和首個死亡"
T["Nur fuer die Fehlersuche. Standard: aus"] = "僅用於排查錯誤。預設：關"
T["Nur fuer die Gildenleitung"] = "僅限公會管理"
T["Nur fuers Aussehen"] = "僅外觀用"
T["Nur guenstig"] = "僅便宜的"
T["Nur handelbare (nicht seelengebundene) Teile. Werte nach Klasse und Rolle wie beim Verbesserungs-Pfeil; Bank zaehlt erst nach einmal Oeffnen."] = "僅可交易（非靈魂繫結）物品。按職業和職責評估，與提升箭頭相同；銀行需開啟一次後才計入。"
T["Nur in der offenen Welt; kann viele Eintraege erzeugen"] = "僅在開放世界；可能產生大量條目"
T["Nur in einer Gruppe und mit der Quest im Log."] = "僅在隊伍中且任務在日誌中時。"
T["Nur in einer Gruppe."] = "僅在隊伍中。"
T["Nur mein Gebiet"] = "僅我的區域"
T["Nur meine"] = "僅我的"
T["Nur mit Helfern"] = "僅有助手的"
T["Nur mit Upgrades"] = "僅有提升的"
T["Nur neue"] = "僅新的"
T["Nur offene Challenges, die zu deinen Charakteren passen (Klassen, Berufe) - plus alle Dungeons, Raids, PvP und Abenteuer."] = "僅顯示適合你角色（職業、專業）的未完成挑戰 - 外加所有地下城、團隊副本、PvP和冒險。"
T["Nur ohne Belohnungs-Auswahl und ohne Kosten. Shift = aussetzen."] = "僅限無獎勵選擇且無花費的。Shift = 跳過。"
T["Nur online"] = "僅線上"
T["Nur von Leitern, bei denen du ueber Oasis angefragt hast"] = "僅來自你通過Oasis申請過的領導"
T["Nur von Oasis-Nutzern"] = "僅來自Oasis使用者"
