T["Wenn jemand online kommt"] = "有人上線時"
T["Wer"] = "誰"
T["Wer Daten schickt, die bei anderen abgelehnt werden (keine Rechte, gefaelschter Urheber, ausgedachte Eintraege). Ein unveraendertes Oasis tut das praktisch nie - ein Hinweis, kein Beweis."] = "傳送了被其他人拒絕的資料的人（無許可權、偽造來源、虛構條目）。未修改的Oasis幾乎不會這樣 - 這只是提示，不是證據。"
T["Wer Interesse meldet, erscheint hier auf einem passenden Platz. Steht ein Termin, meldest du dich direkt auf der Karte an."] = "表示興趣的人會出現在這裡合適的位置。活動確定後，直接在卡片上報名。"
T["Wer aus der Gilde das Item auf der Wunschliste hat"] = "公會中誰的願望單上有此物品"
T["Wer den Bereich in der Navigation sieht (die Gildenleitung sieht immer alles)"] = "誰能在導航中看到此模組（公會管理始終能看到全部）"
T["Wer die Gilde verlassen hat oder entfernt wurde. Kommt jemand zurueck, meldet Oasis das der Gildenleitung."] = "離開公會或被移除的人。如有人回來，Oasis會通知公會管理。"
T["Wer die Krone oben sieht. Ohne Rechte ist sie grau und oeffnet nur eine Vorschau."] = "誰能看到頂部的王冠。無許可權時王冠為灰色，只打開預覽。"
T["Wer eine Nachricht oben im Gildenchat anpinnen darf"] = "誰可以在公會聊天頂部置頂訊息"
T["Wer einladen darf, ist noch nicht bekannt - logge einmal mit deinem Main ein, dann merkt sich Oasis die Gildenleitung."] = "尚不知道誰有邀請許可權 - 用你的大號登入一次，Oasis會記住公會管理。"
T["Wer geht mit nach %s? Ich suche %s"] = "誰一起去%s？我在找%s"
T["Wer hat ...?"] = "誰有……？"
T["Wer hat das Questitem, das du brauchst? Und wem kannst du helfen?"] = "誰有你需要的任務物品？你又能幫誰？"
T["Wer hat was bekommen"] = "誰得到了什麼"
T["Wer im Raid Punkte (Einsatz/Beute) buchen darf."] = "誰可以在團隊中記錄點數（出勤/戰利品）。"
T["Wer in Gruppe oder Raid welche Buffs hat - und was noch fehlt"] = "隊伍或團隊中誰有哪些增益 - 還缺什麼"
T["Wer ist bereit? Ampeln je Spieler"] = "誰已就緒？每位玩家的狀態燈"
T["Wer ist diese Woche schon gebunden, wer ist frei und freigeschaltet - Mains und Twinks"] = "本週誰已鎖定，誰空閒且已解鎖 - 大號和小號"
T["Wer ist online"] = "誰線上"
T["Wer ist online?"] = "誰線上？"
T["Wer ist wann online"] = "誰在什麼時間線上"
T["Wer ist wie weit"] = "誰進度如何"
T["Wer kann was herstellen, Markt, Gildenbank"] = "誰能製作什麼、市場、公會銀行"
T["Wer koennte mit: %s"] = "可能同去的：%s"
T["Wer koennte mit?"] = "誰可能同去？"
T["Wer oft dabei ist und wenig bekommen hat, ist bei 'Bedarf' zuerst dran. Jede Woche verfaellt ein Teil der Punkte."] = "經常參加且獲得較少的人在“需求”時優先。每週會衰減一部分點數。"
T["Wer sich mit passender Rolle meldet, wird sofort in deine Gruppe eingeladen."] = "以合適職責報名的人會立即被邀請到你的隊伍。"
T["Wer steht wo bei welcher Fraktion? Kurz vor dem Ziel, gemeinsam farmen, Fortschritt dieser Woche"] = "誰在哪個陣營的什麼聲望？即將達成、一起刷、本週進度"
T["Wer teilt am meisten aus, heilt am meisten, steckt am meisten ein?"] = "誰輸出最多、治療最多、承受最多？"
T["Wer zur Gildenleitung gehoert, legt der Gildenmeister unter Krone > Gilde fest."] = "公會管理成員由會長在王冠 > 公會中設定。"
T["Werbung"] = "招募"
T["Werte"] = "屬性"
T["Werte bringen deiner Rolle nichts"] = "這些屬性對你的職責無用"
T["Werte nur zur Info"] = "屬性僅供參考"
T["Werte, Jahrbuch, Tagesziel, Rekorde und Abenteuer deines Charakters."] = "你角色的屬性、年鑑、每日目標、紀錄和冒險。"
T["Werte: +Heilung, Intelligenz, Willenskraft, Mana-Reg.;Waffe: Stab oder Einhandwaffe + Nebenhand mit Heilung;Heilen: Verjuengung und Nachwachsen vorab, Heilende Beruehrung fuer grosse Treffer;Tipp: Anregen fuer Mana, Wiedergeburt fuer gefallene Heiler"] = "屬性：+治療、智力、精神、法力回覆;武器：法杖或單手武器 + 帶治療的副手;治療：預先回春術和癒合，大傷害用治療之觸;提示：用啟用回藍，用復生救倒下的治療"
T["Werte: +Heilung, Intelligenz, Zauber-Krit (Erleuchtung gibt Mana zurueck), Mana-Reg.;Waffe: Einhandwaffe + Nebenhand/Schild mit Heilung;Heilen: Lichtblitz fuer kleinen Schaden, Heiliges Licht (niedriger Rang) fuer grosse Treffer;Tipp: Segen verteilen, Gottesschutz wenn du gezogen wirst"] = "屬性：+治療、智力、法術暴擊（啟迪返還法力）、法力回覆;武器：單手武器 + 帶治療的副手/盾牌;治療：小傷害用聖光閃現，大傷害用聖光術（低階）;提示：分發祝福，被攻擊時用聖佑術"
T["Werte: +Heilung, Mana-Reg. (MP5), Intelligenz - Willenskraft bringt wenig;Waffe: Einhandwaffe + Schild mit Heilung;Heilen: Kettenheilung fuer Gruppen, Welle der Heilung (niedriger Rang) fuer den Tank;Tipp: Manaquelle-Totem stellen, Erdschild auf den Tank"] = "屬性：+治療、法力回覆（MP5）、智力 - 精神作用不大;武器：單手武器 + 帶治療的盾牌;治療：團隊用治療鏈，坦克用治療波（低階）;提示：放置法力之泉圖騰，給坦克上大地之盾"
T["Werte: +Heilung, Willenskraft (Meditation: Regeneration auch beim Zaubern), Intelligenz, Mana-Reg.;Waffe: Stab oder Einhandwaffe + Nebenhand mit Heilung, Zauberstab;Heilen: Erneuerung und Machtwort: Schild vorab, Grosse Heilung (niedriger Rang) fuer den Tank;Tipp: Gebet der Heilung fuer die Gruppe, Verblassen bei Aggro"] = "屬性：+治療、精神（冥想：施法時也回覆）、智力、法力回覆;武器：法杖或單手武器 + 帶治療的副手、魔杖;治療：預先恢復和真言術：盾，坦克用強效治療術（低階）;提示：隊伍用治療禱言，仇恨過高時用漸隱術"
T["Werte: Ruestung (Baerengestalt vervielfacht sie), Ausdauer, Beweglichkeit (Ausweichen + Ruestung);Waffe: egal fuer den Schaden - nur die Werte zaehlen (Stab/Stangenwaffe mit Ausdauer);Rotation: Zermalmen, Prankenhieb fuer Gruppen, Demoralisierendes Gebruell;Tipp: Staerke fuer mehr Bedrohung, Wutanfall zum Start"] = "屬性：護甲（熊形態大幅提升）、耐力、敏捷（躲閃 + 護甲）;武器：對傷害無影響 - 只看屬性（帶耐力的法杖/長柄武器）;迴圈：槌擊、揮擊打群體、挫志咆哮;提示：力量增加威脅，開場用激怒"
T["Werte: Staerke (1 Punkt = 2 AP), Beweglichkeit (AP + Krit), Krit, Treffer bis +9 %;Waffe: egal fuer den Schaden - nur die Werte zaehlen;Rotation: Krallenhieb/Schreddern fuer Combopunkte, dann Wilder Biss;Tipp: Machtwandel (Gestalt neu) fuer Energie, aus dem Schleichen anspringen"] = "屬性：力量（1點 = 2攻擊強度）、敏捷（攻擊強度 + 暴擊）、暴擊、命中至+9 %;武器：對傷害無影響 - 只看屬性;迴圈：爪擊/撕碎攢連擊點，然後兇猛撕咬;提示：用變形重置（重新變形）回能量，從潛行中突襲"
T["Werte: Staerke (1 Punkt = 2 AP), Krit (loest Schlaghagel aus = schneller schlagen), Treffer bis +9 %;Waffe: langsame Zweihandwaffe - Windzorn trifft pro Schlag, also je langsamer desto mehr Schaden;Rotation: Windzorn-Waffe, Sturmschlag, Erdschock;Tipp: Totem der Staerke der Erde und Windzorn-Totem fuer die Gruppe"] = "屬性：力量（1點 = 2攻擊強度）、暴擊（觸發亂舞 = 攻速更快）、命中至+9 %;武器：慢速雙手武器 - 風怒按每次攻擊觸發，越慢傷害越高;迴圈：風怒武器、風暴打擊、地震術;提示：為隊伍放置大地之力圖騰和風怒圖騰"
T["Werte: Staerke (1 Punkt = 2 AP), Krit, Treffer bis +9 %;Waffe: langsamer Zweihaender - Siegel und Richturteil wirken pro Schlag;Rotation: Siegel der Rechtschaffenheit/des Befehls, Richturteil, Siegel neu setzen;Tipp: Weihe nur mit genug Mana, Segen der Macht fuer dich"] = "屬性：力量（1點 = 2攻擊強度）、暴擊、命中至+9 %;武器：慢速雙手武器 - 聖印和審判按每次攻擊生效;迴圈：正義聖印/命令聖印、審判、重新施放聖印;提示：法力充足時才用奉獻，給自己上力量祝福"
T["Werte: Treffer bis +9 %, Beweglichkeit (1 AP, ca. 29 = 1 % Krit), AP, Krit;Waffe: Kampf = schnelle Nebenhand, langsame Haupthand (Finsterer Stoss); Dolche fuer Meucheln;Rotation: Combopunkte aufbauen, Zerhaecksler oben halten, dann Ausweiden;Tipp: mit zwei Waffen verfehlen normale Schlaege oefter - Treffer ist am wichtigsten"] = "屬性：命中至+9 %、敏捷（1攻擊強度，約29 = 1 %暴擊）、攻擊強度、暴擊;武器：戰鬥 = 快速副手、慢速主手（邪惡攻擊）; 刺殺用匕首;迴圈：攢連擊點、保持切割、然後剔骨;提示：雙持時普通攻擊更容易未命中 - 命中最重要"
T["Werte: Treffer bis +9 %, Beweglichkeit (2 Distanz-AP, ca. 53 = 1 % Krit), AP, Intelligenz;Waffe: langsame Distanzwaffe (hoher Schaden pro Schuss), Nahkampfwaffe mit Werten;Rotation: Mal des Jaegers, Automatischer Schuss, Zielschuss/Mehrfachschuss dazwischen;Tipp: Begleiter fuettern und gluecklich halten, Eisfalle (Quadrat) als Kontrolle"] = "屬性：命中至+9 %、敏捷（2遠端攻擊強度，約53 = 1 %暴擊）、攻擊強度、智力;武器：慢速遠端武器（每發傷害高）、帶屬性的近戰武器;迴圈：獵人印記、自動射擊、穿插瞄準射擊/多重射擊;提示：餵養寵物並保持快樂，冰凍陷阱（方塊）用於控制"
T["Werte: Treffer bis +9 %, Staerke (1 Punkt = 2 AP), Krit (ca. 20 Beweglichkeit = 1 %);Waffe: langsamer Zweihaender (Toedlicher Stoss, Heldenhafter Stoss wirken pro Schlag);Rotation: Wut aufbauen, Toedlicher Stoss / Blutdurst, Wirbelwind, ueberschuessige Wut in Heldenhaften Stoss;Tipp: Kampfrausch-Ruf vor dem Kampf, Hinrichten unter 20 % Leben"] = "屬性：命中至+9 %、力量（1點 = 2攻擊強度）、暴擊（約20敏捷 = 1 %）;武器：慢速雙手武器（致死打擊、英勇打擊按每次攻擊生效）;迴圈：積攢怒氣、致死打擊/嗜血、旋風斬、多餘怒氣用英勇打擊;提示：戰前用戰鬥怒吼，20 %血量以下用斬殺"
T["Werte: Verteidigung (440 = auf 60 kritsicher gegen Bosse), Ausdauer, Ruestung, Schildblock;Waffe: Einhandwaffe + Schild, schnelle Waffe = mehr Wut;Rotation: Schildschlag/Rachsucht, Ruestung zerreissen auf das Ziel, Heldenhafter Stoss bei viel Wut;Tipp: Treffer hilft, damit Spott und Faehigkeiten nicht verfehlen"] = "屬性：防禦（60級440防禦免疫首領暴擊）、耐力、護甲、盾牌格擋;武器：單手武器 + 盾牌，快速武器 = 更多怒氣;迴圈：盾牌猛擊/復仇、對目標破甲、怒氣多時用英勇打擊;提示：命中有助於嘲諷和技能不被未命中"
T["Werte: Verteidigung, Ausdauer, Ruestung, dann Zauberschaden fuer mehr Bedrohung;Waffe: Einhandwaffe (gern mit Zauberschaden) + Schild;Rotation: Zorn der Gerechtigkeit an, Weihe fuer Gruppen, Heiliger Schild oben halten;Tipp: Mana ist knapp - Siegel der Weisheit oder Intelligenz mitnehmen"] = "屬性：防禦、耐力、護甲，然後法術傷害以提高威脅;武器：單手武器（最好帶法術傷害）+ 盾牌;迴圈：開啟正義之怒、群體用奉獻、保持神聖之盾;提示：法力緊張 - 帶上智慧聖印或智力"
T["Werte: Zauberschaden, Zauber-Krit (Elementarfokus spart Mana), Intelligenz, Mana-Reg.;Waffe: Einhandwaffe + Schild/Nebenhand mit Zauberschaden;Rotation: Blitzschlag spammen, Kettenblitz bei Gruppen, Flammenschock;Tipp: Zaubertreffer bis +16 % im Raid, Manaquelle-Totem gegen leeres Mana"] = "屬性：法術傷害、法術暴擊（元素集中節省法力）、智力、法力回覆;武器：單手武器 + 帶法術傷害的盾牌/副手;迴圈：狂按閃電箭、群體用閃電鏈、烈焰震擊;提示：團隊中法術命中至+16 %，用法力之泉圖騰防止空藍"
T["Werte: Zauberschaden, Zauber-Krit, Intelligenz, Zaubertreffer bis +16 % im Raid;Waffe: Stab oder Einhandwaffe + Nebenhand mit Zauberschaden;Rotation: Mondfeuer + Insektenschwarm, dann Zorn oder Sternenfeuer;Tipp: Anregen fuer dich selbst, wenn das Mana knapp wird"] = "屬性：法術傷害、法術暴擊、智力、團隊中法術命中至+16 %;武器：法杖或單手武器 + 帶法術傷害的副手;迴圈：月火術 + 蟲群，然後憤怒或星火術;提示：法力緊張時給自己用啟用"
T["Werte: Zauberschaden, Zaubertreffer bis +16 % (Raid), Ausdauer, Intelligenz;Waffe: Stab oder Dolch + Nebenhand mit Zauberschaden, Zauberstab fuer Restmana;Rotation: Verderbnis + Fluch, dann Schattenblitz; Aderlass statt Trinken;Tipp: Ausdauer lohnt sich doppelt (Aderlass, Leerwandler/Seelenverbindung)"] = "屬性：法術傷害、法術命中至+16 %（團隊）、耐力、智力;武器：法杖或匕首 + 帶法術傷害的副手，魔杖用於剩餘法力;迴圈：腐蝕術 + 詛咒，然後暗影箭; 用生命分流代替喝水;提示：耐力有雙重收益（生命分流、虛空行者/靈魂連結）"
T["Werte: Zauberschaden, Zaubertreffer bis +16 % (Raid), Willenskraft fuer Mana;Waffe: Stab oder Einhandwaffe + Nebenhand mit Zauberschaden;Rotation: Schattenwort: Schmerz, Gedankenschlag, Gedankenschinden;Tipp: Schattengestalt dauerhaft an, Vampirumarmung heilt die Gruppe"] = "屬性：法術傷害、法術命中至+16 %（團隊）、精神回法力;武器：法杖或單手武器 + 帶法術傷害的副手;迴圈：暗言術：痛、心靈震爆、精神鞭笞;提示：保持暗影形態，吸血鬼的擁抱治療隊伍"
T["Werte: Zauberschaden, dann Zaubertreffer bis +16 % (Raid-Bosse), Intelligenz, Zauber-Krit;Waffe: Stab mit Zauberschaden, dazu ein Zauberstab fuer Restmana;Rotation: Frostblitz bzw. Feuerball spammen, Hervorrufung bei leerem Mana;Leveln: Intelligenz und Willenskraft = weniger Pausen, in Gruppen Schaf (Mond) setzen"] = "屬性：法術傷害，然後法術命中至+16 %（團隊首領）、智力、法術暴擊;武器：帶法術傷害的法杖，加一根魔杖用於剩餘法力;迴圈：狂按寒冰箭或火球術，空藍時用喚醒;升級：智力和精神 = 更少休息，組隊時用變羊（月亮）"
T["Wertung"] = "評分"
