T["1.  Kampflog mitschreiben lassen (Einstellungen > Bereiche > Kampf-Rangliste, steht auf an).\n2.  Nach dem Spielen im Oasis-Ordner ImportCrits.bat doppelklicken.\n3.  Im Spiel /reload - dein hoechster Crit steht hier und wird mit der Gilde geteilt."] = "1.  保持戰鬥日誌開啟（設定 > 模組 > 戰鬥排行榜，預設開啟）。\n2.  遊戲結束後，雙擊 Oasis 資料夾中的 ImportCrits.bat。\n3.  在遊戲中 /reload - 你的最高暴擊會顯示在這裡並與公會共享。"
