T["Aktiv: Meme-Sounds, Musik und Gilden-Emojis sind enthalten."] = "已啟用：包含梗音效、音樂和公會表情。"
T["Aktive Mitglieder unterhalb der Offiziersraenge erscheinen nach so vielen Tagen im selben Rang in der Liste 'Befoerderung'. 0 = aus."] = "官員會階以下的活躍成員在同一會階停留這麼多天後，會出現在“晉升”列表中。0 = 關閉。"
T["Aktuelles Gebiet zuerst"] = "當前區域優先"
T["Alle Bereiche, nach Themen gruppiert: Gilde, Zusammen spielen, Raid, Handel, Spass. Ein Klick auf eine Ueberschrift klappt die Gruppe zu."] = "所有模組按主題分組：公會、一起玩、團隊、交易、娛樂。點選標題可摺疊該組。"
T["Alle Gebiete aufklappen"] = "展開所有區域"
T["Alle Gebiete zuklappen"] = "摺疊所有區域"
T["Alle Mitglieder mit Rang, Stufe und Oasis-Version. Rechtsklick auf eine Zeile: Rang aendern."] = "所有成員及其會階、等級和 Oasis 版本。右鍵點選一行：更改會階。"
T["Alle Schriften unter der SIL Open Font License 1.1"] = "所有字型均採用 SIL Open Font License 1.1"
T["Alle: Brennendes Adrenalin: SOFORT aus dem Raid laufen (du stirbst gleich).\nAlle: Volle Ressourcen am Anfang - alles raushauen.\nTank: Tank-Reihenfolge festlegen (Adrenalin auf dem Tank).\nDD: Nicht vor oder hinter den Drachen."] = "All: 燃燒刺激：立刻跑出團隊（你馬上就會死）。\nAll: 開場資源全滿 - 全力輸出。\nTank: 安排坦克順序（燃燒刺激會點坦克）。\nDD: 不要站在龍的正面或背後。"
T["Alle: Die 8 Feuerwichtel nicht in der Naehe des Raids sterben lassen (Explosion).\nTank: Jeder Wichtel-Tank zieht seinen Wichtel weg, Hexer verbannen.\nHeiler: Bannen, Wichtel-Tanks im Blick.\nDD: Garr zuerst, Wichtel nur gezielt."] = "All: 不要讓 8 個火誓者死在團隊附近（爆炸）。\nTank: 每個小怪坦克把自己的火誓者拉開，術士放逐。\nHealer: 驅散，留意小怪坦克。\nDD: 先打加爾，小怪聽指揮再打。"
T["Alle: Die beiden Kernhunde weg vom Boss tanken, nicht toeten.\nTank: Golemagg-Tank wechseln, wenn Magmasplitter zu hoch stapeln.\nDD: Nur auf Golemagg."] = "All: 把兩隻熔火怒犬拉離首領坦住，不要擊殺。\nTank: 熔岩飛濺疊得太高時更換古雷曼格坦克。\nDD: 只打古雷曼格。"
T["Alle: Erst die 4 Priester, sie heilen sich gegenseitig.\nTank: Herold und Priester getrennt.\nDD: Unterbrechen! Dunkle Besserung der Priester stoppen."] = "All: 先殺 4 個牧師，它們會互相治療。\nTank: 把薩弗隆和牧師分開。\nDD: 打斷！阻止牧師的黑暗治癒。"
T["Alle: Feuerschutz! Wrath of Ragnaros wirft den Nahkampf weg - danach wieder ran.\nAlle: Phase der Soehne (nach 3 Min oder bei Untertauchen): alle Soehne der Flamme toeten.\nTank: Zweiter Tank bereit, wenn der erste weggeworfen wird.\nHeiler: Verteilt, Fernkampf nicht zu nah (Lavaplatscher).\nDD: Nahkampf: Mana unter Kontrolle, Fernkampf auf Abstand."] = "All: 火焰抗性！拉格納羅斯之怒會擊退近戰 - 之後再回去。\nAll: 烈焰之子階段（3 分鐘後或他下潛時）：擊殺所有烈焰之子。\nTank: 第二坦克隨時準備接手被擊飛的主坦克。\nHealer: 分散站位，遠端不要靠太近（熔岩爆裂）。\nDD: 近戰：控制好法力，遠端保持距離。"
T["Alle: Flammenpuffer stapelt - Fernkampf hinter Saeulen zum Abbauen.\nTank: Zwei Tanks hinter Saeulen, Flugelschlag wirft zurueck.\nDD: Onyxiaschuppenumhang Pflicht."] = "All: 烈焰打擊會疊加 - 遠端躲到柱子後消層。\nTank: 兩個坦克躲在柱子後，龍翼打擊會擊退。\nDD: 必須裝備奧妮克希亞鱗片披風。"
T["Alle: Fluch des Gehennas (weniger Heilung) sofort entfernen.\nAlle: Aus dem Feuerregen raus.\nTank: Die zwei Flammenwichtel getrennt tanken.\nDD: Wichtel zuerst, dann Gehennas."] = "All: 立刻解除基赫納斯的詛咒（治療效果降低）。\nAll: 離開火焰之雨。\nTank: 把兩個烈焰行者分開坦。\nDD: 先殺烈焰行者，再打基赫納斯。"
T["Alle: Fluch des Lucifron und Drohende Verdammnis sofort entfernen (Magier/Druiden, Priester/Paladine).\nTank: Die beiden Wachen getrennt tanken - Gedankenkontrolle!\nHeiler: Verteilt stehen, gedankenkontrollierte Spieler bannen.\nDD: Erst die Wachen, dann Lucifron."] = "All: 立刻解除魯西弗隆的詛咒和末日降臨（法師/德魯伊、牧師/聖騎士）。\nTank: 把兩個護衛分開坦 - 小心精神控制！\nHealer: 分散站位，驅散被精神控制的玩家。\nDD: 先殺護衛，再打魯西弗隆。"
T["Alle: Lebende Bombe: SOFORT raus aus dem Raid laufen!\nAlle: Inferno - weg vom Boss, Mana-Ausloeschung bannen.\nTank: Mitte halten, bei Inferno kurz raus.\nDD: Nahkampf bei Inferno zurueck."] = "All: 活體炸彈：立刻跑出團隊！\nAll: 地獄火 - 遠離首領，驅散點燃法力。\nTank: 守住中間，地獄火時短暫離開。\nDD: 地獄火時近戰後撤。"
T["Alle: Magiereflexion/Schadensschild der Wachen beachten - dann Schaden stoppen.\nTank: Jeder Tank eine Wache, Magier schafen die Elitewachen.\nDD: Heiler-Wachen (Flamewaker Healer) zuerst."] = "All: 注意護衛的魔法反射/傷害護盾 - 此時停止輸出。\nTank: 每個坦克一個護衛，法師變羊精英護衛。\nDD: 先殺治療護衛（Flamewaker Healer）。"
T["Alle: Nie vor oder hinter Onyxia stehen (Atem und Schwanzfeger).\nAlle: Phase 2 (65%): Feuerbaellen ausweichen, nicht in die Hoehlen-Eingaenge.\nAlle: Phase 3 (40%): Furcht - Furchtschutz/Erdungstotem bereit, Lava-Risse meiden.\nTank: Onyxia seitlich an der Wand, Kopf weg vom Raid.\nTank: Phase 2: Welpen einsammeln. Phase 3: Aggro sofort zurueck.\nHeiler: Tank hat Vorrang, in Phase 2 verteilt stehen.\nDD: 3 Angriffe des Tanks abwarten. Phase 2: Welpen zuerst."] = "All: 絕不要站在奧妮克希亞的正面或背後（吐息和掃尾）。\nAll: 第 2 階段（65%）：躲開火球，不要進入洞穴入口。\nAll: 第 3 階段（40%）：恐懼 - 準備好防護恐懼結界/戰慄圖騰，避開熔岩裂縫。\nTank: 把奧妮克希亞側向貼牆，頭部背對團隊。\nTank: 第 2 階段：收攏雛龍。第 3 階段：立刻拉回仇恨。\nHealer: 坦克優先，第 2 階段分散站位。\nDD: 等坦克攻擊 3 次再打。第 2 階段：先殺雛龍。"
T["Alle: Panik - Furchtschutz/Erdungstotem, Jaeger: Einlullender Schuss bei Raserei.\nAlle: Aus dem Lavafeuer am Boden raus.\nTank: Magmadar mit dem Ruecken zum Raid.\nDD: Fernkampf hinten verteilt."] = "All: 恐慌 - 防護恐懼結界/戰慄圖騰，獵人：狂暴時使用寧神射擊。\nAll: 離開地上的熔岩火焰。\nTank: 讓瑪格曼達背對團隊。\nDD: 遠端在後方分散站位。"
T["Alle: Phase 1: Drachkin aus beiden Seiten, Klassenrufe beachten.\nAlle: Phase 3 (20%): Skelette wieder auferstanden - erneut toeten.\nTank: Nefarian an der Wand, Furcht - Furchtschutz.\nHeiler: Klassenruf fuer Priester: Heilung schadet - aufpassen.\nDD: Jaeger/Krieger: Klassenrufe beachten (Waffen weg, Haltung)."] = "All: 第 1 階段：龍人從兩側出現，注意職業點名。\nAll: 第 3 階段（20%）：骷髏再次復活 - 再殺一遍。\nTank: 把奈法利安拉到牆邊，恐懼 - 防護恐懼結界。\nHealer: 牧師職業點名：治療會造成傷害 - 小心。\nDD: 獵人/戰士：注意職業點名（武器損壞、姿態）。"
T["Alle: Phase 1: Eier zerstoeren (Gedankenkontrolle der Kugel), Adds abfangen.\nAlle: Nach allen Eiern: Boss im Raum - Feuerball-Nova.\nTank: Adds an den Treppen sammeln.\nDD: Magier und Drachkin zuerst."] = "All: 第 1 階段：摧毀龍蛋（通過寶珠精神控制），接住小怪。\nAll: 龍蛋全毀後：首領進入房間 - 火焰新星。\nTank: 在樓梯處聚攏小怪。\nDD: 先殺法師和龍人。"
T["Alle: Raserei - Jaeger: Einlullender Schuss.\nTank: Zwei Tanks, Flugelschlag beachten.\nDD: Onyxiaschuppenumhang Pflicht."] = "All: 狂暴 - 獵人：寧神射擊。\nTank: 兩個坦克，注意龍翼打擊。\nDD: 必須裝備奧妮克希亞鱗片披風。"
T["Alle: Schatten der Schattenschwinge heilt den Boss - Tank mit Debuff tauscht.\nTank: Zwei Tanks wechseln bei Schatten.\nDD: Onyxiaschuppenumhang Pflicht."] = "All: 埃博諾克之影會治療首領 - 中了減益的坦克換坦。\nTank: 兩個坦克在中埃博諾克之影時交換。\nDD: 必須裝備奧妮克希亞鱗片披風。"
T["Alle: Stoss zurueck - an die Wand stellen.\nTank: Zwei Tanks, Aggro wird durch Niederschlagen geteilt.\nDD: Mortalschlag auf Tank: Heiler vorbereiten."] = "All: 擊退 - 貼牆站位。\nTank: 兩個坦克，擊飛會分攤仇恨。\nDD: 坦克中致死打擊：治療做好準備。"
T["Alle: Teleportiert sich - wer Aggro hat, nicht wegrennen.\nAlle: Fluch des Shazzrah entfernen, Arkane Explosion: Nahkampf auf Abstand.\nTank: Nach jedem Blinzeln sofort wieder ran.\nHeiler: Bannen (Deaktivieren-Magie)."] = "All: 他會傳送 - 獲得仇恨的人不要跑開。\nAll: 解除沙斯拉爾的詛咒，魔爆術：近戰保持距離。\nTank: 每次閃現後立刻重新貼上。\nHealer: 驅散（衰減魔法）。"
T["Alle: Zwei der fuenf Atem-Arten je Woche - Atem verlaesst man hinter der Ecke.\nAlle: Hourglass Sand fuer Bronze-Affliktion.\nTank: Am Tor tanken, Raid hinter der Ecke.\nDD: Bei Raserei Einlullender Schuss."] = "All: 每週從五種吐息中出現兩種 - 躲到拐角後規避吐息。\nAll: 用沙漏之沙解除青銅減益。\nTank: 在門口坦，團隊站在拐角後。\nDD: 狂暴時使用寧神射擊。"
T["Alt halten: alle Werte und Bewertung. Shift: Blizzard-Vergleich."] = "按住 Alt：全部屬性和評分詳情。Shift：暴雪對比。"
T["Alt loslassen: kompakter Vergleich. Shift: Blizzard-Vergleich."] = "鬆開 Alt：簡潔對比。Shift：暴雪對比。"
T["Altes Oasis"] = "舊版 Oasis"
T["An: mit der Maus an eine eigene Stelle ziehen. Aus: haengt am Talentfenster."] = "開啟：用滑鼠拖到任意位置。關閉：停靠在天賦視窗旁。"
T["Anfuehrer der Dunkelspeere"] = "暗矛部族的領袖"
T["Angefangener Text bleibt beim Wechsel des Gespraechs stehen"] = "切換對話時保留未傳送的文字"
T["Animationen aus"] = "關閉動畫"
T["Ansprechpartner"] = "聯絡人"
T["Anwesenheit und Ausruestung der Gilde im Blick."] = "隨時掌握出勤和公會裝備情況。"
T["Auf dem Flug nichts erkennen oder melden"] = "飛行途中不檢測也不報告"
T["Auf dem Flugmeister-Flug kannst du ohnehin nicht anhalten"] = "反正飛行途中你也停不下來"
T["Aus FojjiCore (%d)"] = "來自 FojjiCore (%d)"
T["Aus Guides zur Forever-Beta - kann sich noch aendern."] = "來自 Forever 測試版攻略 - 仍可能變動。"
T["Aus dem Soundpaket (ruhig)"] = "來自音效包（柔和）"
T["Aus: das Fenster verschwindet. Zurueck mit /oa builds."] = "關閉：視窗消失。使用 /oa builds 恢復。"
T["Ausfuehrliche Karten"] = "詳細卡片"
T["Ausklappen"] = "展開"
T["Ausloggen: Blizzards Dialogliste war von Oasis beruehrt (ab 0.5.478 behoben - bitte Oasis aktualisieren)."] = "登出：暴雪的對話方塊列表被 Oasis 汙染（0.5.478 已修復 - 請更新 Oasis）。"
T["Banner auf der Uebersicht: Midas, das Auktionshaus-Addon von Rebo aus der Gilde OASIS"] = "概覽橫幅：Midas，公會 OASIS 的 Rebo 製作的拍賣行外掛"
T["Befoerderung vorschlagen nach"] = "建議晉升的天數"
T["Beim naechsten Wurf siehst du alt aus!"] = "下一把你就完了！"
T["Beispieldaten gibt es nur in der Entwicklerversion."] = "示例資料僅在開發者版本中提供。"
T["Bereiche freigeben"] = "開放模組"
T["Bereit fuer den Pull? Bereitschaft, Verzauberungen und Buffs je Spieler"] = "準備開怪了嗎？每位玩家的就位狀態、附魔和增益"
T["Bestaetigte Crit-Rekorde aus der Logdatei importiert."] = "已從日誌檔案匯入確認的暴擊紀錄。"
T["Beta-Geschenk"] = "測試版禮物"
T["Beute automatisch verteilen, wenn du Pluendermeister bist"] = "你是戰利品分配者時自動分配戰利品"
T["Beuterat ab Rang"] = "拾取委員會起始會階"
T["Bilder / Sek."] = "幀/秒"
T["Bilder ueber 1 ms (seit Sitzungsbeginn): %d"] = "超過 1 毫秒的幀（本次會話）：%d"
T["Bitte den Namen eines Gildenmitglieds eingeben (nicht einen eigenen Charakter)."] = "請輸入一名公會成員的名字（不是你自己的角色）。"
T["Blockiert"] = "被阻止"
T["Blockierung von %s beobachtet; Ausloeser nicht bestaetigt."] = "觀察到 %s 被阻止；原因尚未確認。"
T["Boss der Defias"] = "迪菲亞的首領"
T["Boss von Ratschet - alles hat seinen Preis"] = "棘齒城的老闆 - 一切皆有價碼"
T["Boss-Positionen im Dungeon-Atlas und Drop-Chancen der Dungeon-Bosse - GPL-2.0. Autoren: Lag, Daviesh und weitere"] = "地下城圖集中的首領位置和地下城首領掉落率 - GPL-2.0。作者：Lag、Daviesh 等"
T["Bosse & Beute"] = "首領與戰利品"
T["Brutmutter der Schwarzdrachen"] = "黑龍軍團的育母"
T["Building: Auswahl"] = "Building：選擇"
T["Building: Bestaetigen"] = "Building：確認"
T["Building: Fenster auf"] = "Building：開啟視窗"
T["Building: Fenster zu"] = "Building：關閉視窗"
T["Building: Hinweis"] = "Building：提示"
T["Building: Klick"] = "Building：點選"
T["Building: Schalter"] = "Building：開關"
T["Builds aus der Gilde ausgeblendet. Wieder einblenden: /oa builds"] = "公會天賦配置已隱藏。重新顯示：/oa builds"
T["Builds aus der Gilde wird wieder neben dem Talentfenster gezeigt."] = "公會天賦配置重新顯示在天賦視窗旁。"
T["Cairne Bluthuf"] = "凱恩·血蹄"
T["Casual: Auswahl"] = "Casual：選擇"
T["Casual: Bestaetigen"] = "Casual：確認"
T["Casual: Fenster auf"] = "Casual：開啟視窗"
T["Casual: Fenster zu"] = "Casual：關閉視窗"
T["Casual: Hinweis"] = "Casual：提示"
T["Casual: Klick"] = "Casual：點選"
T["Casual: Schalter"] = "Casual：開關"
T["Charakterstatistik - hoechster Einzelwert, Crit-Status unbekannt"] = "角色統計 - 最高單次數值，暴擊狀態未知"
T["Chat-Eingabe und Zauberbefehle koennen beteiligt sein."] = "可能與聊天輸入和施法命令有關。"
T["Chat-Eingabe und Zielwechsel koennen beteiligt sein."] = "可能與聊天輸入和目標切換有關。"
T["Chatnachrichten erfordern in diesem Client eine direkte Eingabe."] = "此客戶端中聊天訊息需要直接輸入。"
T["Credits"] = "鳴謝"
T["Crit-Heilung"] = "暴擊治療"
T["Crit-Import gehoert zu einem anderen Charakter."] = "暴擊匯入資料屬於另一個角色。"
T["Crit-Quelle pruefen"] = "檢查暴擊來源"
T["Crit-Rekorde aus den Kampflog-Dateien uebernommen."] = "已從戰鬥日誌檔案匯入暴擊紀錄。"
T["Crits beim Kampf allein automatisch zaehlen"] = "單獨戰鬥時自動統計暴擊"
T["Crits in Gruppe und Dungeon schaetzen"] = "估算隊伍和地下城中的暴擊"
T["Das X am Fenster klappt Oasis in die Leiste ein. Das X an der Leiste schliesst ganz."] = "視窗上的 X 將 Oasis 收起到工具欄。工具欄上的 X 則完全關閉。"
T["Das gelbe Ausrufezeichen am Symbol zeigt das an."] = "圖示上的黃色感嘆號表示這一點。"
T["Das war nur Glueck! Nochmal!"] = "那只是運氣！再來！"
T["Das war's schon. Den Rundgang findest du jederzeit wieder unter Einstellungen > Status oder mit /oa rundgang."] = "就這些了。隨時可以在 設定 > 狀態 中或用 /oa rundgang 重新開啟導覽。"
T["Daten"] = "資料"
T["Deckend"] = "不透明"
T["Dein Charakter"] = "你的角色"
T["Deine Stats: Oasis-Rang, Abzeichen und alle Zaehler"] = "你的資料：Oasis 等級、徽章和所有計數"
T["Den Download findest du im Discord der Gilde."] = "下載地址見公會的 Discord。"
T["Der Client erlaubt Oasis nicht, das Kampflog einzuschalten - bitte selbst /combatlog eingeben."] = "客戶端不允許 Oasis 開啟戰鬥日誌 - 請自行輸入 /combatlog。"
T["Der Inhalt des gewaehlten Bereichs. Die Uebersicht zeigt, wer online ist, was ansteht und was es Neues gibt."] = "所選模組的內容。概覽顯示誰線上、即將進行的事項和最新動態。"
T["Der Minimap-Knopf oder /oa oeffnet Oasis. Mit dem Strich oben rechts wird das Fenster zu einer schmalen Leiste."] = "點選小地圖按鈕或輸入 /oa 開啟 Oasis。右上角的橫線可將視窗變為窄工具欄。"
T["Der Offizierskanal (/o) mit Verlauf - nur fuer Raenge mit Offizierschat-Recht."] = "帶歷史記錄的官員頻道（/o）- 僅限擁有官員聊天許可權的會階。"
T["Der gelbe Strich links in der Liste zeigt das an."] = "列表左側的黃色豎條表示這一點。"
T["Details schliessen"] = "關閉詳情"
T["Deutlicher Standard-Ton bei Online-Meldungen"] = "上線提醒使用清晰的預設提示音"
T["Die Charakterstatistik ist in diesem Client nicht verfuegbar."] = "此客戶端不提供角色統計。"
T["Die Gildenleitung hat Soundeffekte fuer dich gesperrt."] = "公會管理層已禁止你使用音效。"
T["Die Leiste ist ab dem Einloggen da und bleibt - das X am Fenster schliesst nur das Fenster."] = "工具欄從登入起就一直顯示 - 視窗上的 X 只關閉視窗。"
T["Die Prozentzahl vergleicht die Item-Wertung fuer deine Rolle, nicht deinen gesamten Schaden. Auswirkungen sind Schaetzwerte."] = "百分比比較的是物品對你職責的評分，而非你的總傷害。效果為估算值。"
T["Die Statistik liefert derzeit keinen lesbaren Wert."] = "該統計目前沒有可讀取的數值。"
T["Die Zentrale eurer Gilde. In 30 Sekunden kennst du dich aus - hier ist das Wichtigste."] = "你們公會的中心。30 秒就能上手 - 這裡是最重要的內容。"
T["Die geschuetzte Funktion wurde blockiert. Der genaue Ausloeser ist noch unbekannt."] = "受保護的函式被阻止。確切原因尚不清楚。"
T["Die passende Charakterstatistik wurde noch nicht gefunden."] = "尚未找到對應的角色統計。"
T["Die vollstaendigen Lizenztexte liegen im Oasis-Ordner: CREDITS.txt, LICENSE und LICENSE-MIT.txt."] = "完整許可文本位於 Oasis 資料夾：CREDITS.txt、LICENSE 和 LICENSE-MIT.txt。"
T["Diese Gildenraenge (0 = Gildenmeister) duerfen im Beuterat abstimmen."] = "這些公會會階（0 = 會長）可在拾取委員會中投票。"
T["Dieser Charakter liegt auf einem anderen WoW-Account und hat dich als Main eingetragen. Nur wenn du bestaetigst, zaehlt er in der Gilde als dein Twink."] = "該角色位於另一個 WoW 賬號，並將你登記為主號。只有你確認後，它才會在公會中算作你的小號。"
T["Dieser Client liefert keine Addon-Messwerte (C_AddOnProfiler fehlt)."] = "此客戶端不提供外掛效能資料（缺少 C_AddOnProfiler）。"
T["Discord Voice"] = "Discord 語音"
T["Discord Voice: an"] = "Discord 語音：開"
T["Discord-Link (kommt in die Nachricht)"] = "Discord 連結（會寫入訊息）"
T["Discord: %s"] = "Discord：%s"
