T["Wer an einem Abend schon ein Item mit Bedarf bekommen hat, rutscht bei Bedarf hinter alle ohne Item (gleicher Wurf-Rang)."] = "當晚已通過需求獲得過物品的人，需求時排在所有未獲得物品的人之後（同一擲骰檔位）。"
T["Wer ein Item fuer den Termin reserviert hat, kommt bei Bedarf vor allen anderen."] = "為該活動預訂了物品的人，需求時優先於其他所有人。"
