T["Wieder am Talentfenster andocken"] = "重新停靠到天賦視窗"
T["WoW sagt Addons in der Gruppe nicht, wer getroffen hat. Oasis zaehlt einen kritischen Treffer nur, wenn er direkt auf deinen eigenen Angriff folgt und nach dem Kampf zur Schadensanzeige passt. In der Rangliste als geschaetzt markiert."] = "在隊伍中 WoW 不會告訴外掛是誰打出的命中。只有當暴擊緊隨你自身的攻擊、且戰鬥後與傷害統計相符時，Oasis 才會計入。在排行榜中標記為估算。"
T["WoW-Klassiker"] = "WoW 經典"
T["Wochenaufgaben %d/%d"] = "每週任務 %d/%d"
T["World of Warcraft und zugehoerige Namen, Wappen und Grafiken sind Marken von Blizzard Entertainment. Oasis ist ein Fan-Projekt und steht in keiner Verbindung zu Blizzard."] = "World of Warcraft 及相關名稱、徽記和影像均為 Blizzard Entertainment 的商標。Oasis 是玩家自制專案，與 Blizzard 無任何關聯。"
T["Wuerfeln: Reihenfolge Bedarf > Zweitspec > Transmog, dann Wurf. Punkte: Prioritaet aus den Beutepunkten entscheidet. Beuterat: Offiziere stimmen ab, der Plundermeister vergibt."] = "擲骰：順序為 需求 > 副天賦 > 幻化，然後比點數。分數：由戰利品分數得出的優先順序決定。拾取委員會：官員投票，戰利品分配者發放。"
T["Zahnrad = Einstellungen (Aussehen, Toene, Hinweise). Daneben Sprache und - fuer die Gildenleitung - die Krone."] = "齒輪 = 設定（外觀、音效、提示）。旁邊是語言，以及公會管理層專用的皇冠。"
T["Zeigt bei gruenen, blauen und epischen Teilen, welche Materialien beim Entzaubern herauskommen koennen"] = "顯示綠色、藍色和史詩物品分解後可能獲得的材料"
T["Zeigt in der Suche an, dass ihr per Sprache redet (Discord o.ae.). Beitreten regelt weiter Blizzard bzw. dein Gruppenleiter."] = "在招募列表中顯示你們使用語音交流（Discord 等）。加入隊伍仍由暴雪/你的隊長處理。"
