T["Zielt jemand einen Boss an, zu dem es eine Taktik gibt, erscheint ein kurzer Hinweis (ausserhalb des Kampfes)."] = "有人選中有戰術的首領時，會顯示簡短提示（非戰鬥狀態下）。"
